import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './Cloud.css';

const CloudPage = () => {
  // Fetch the context hub
  const context = useOutletContext();
  
  // Extract Cloud channel (Fallback to empty object to prevent errors)
  const { data: cloudData, setter: setCloudData } = context?.cloud || {};

  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(false);

  // Sync bridge: Update local view if context data changes
  useEffect(() => {
    if (cloudData && Array.isArray(cloudData)) {
      setProjects(cloudData);
    }
  }, [cloudData]);

  const fetchInfrastructureStatus = async () => {
    setLoading(true);
    try {
      const endpoints = ['p1', 'p2', 'p3', 'p4'];
      const responses = await Promise.all(
        endpoints.map(ep => fetch(`http://localhost:8000/api/cloud/${ep}`))
      );
      const data = await Promise.all(responses.map(r => r.json()));
      
      setProjects(data);
      
      // Update global context hub if setter exists
      if (setCloudData) {
        setCloudData(data);
        console.log("SUCCESS: Cloud telemetry committed globally.");
      } else {
        console.error("ERROR: MainLayout partitioned cloud setter is missing.");
      }
    } catch (error) {
      console.error("Infrastructure link error:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="cloud-container">
      <ProjectNavbar basePath="cloud" links={["Fleet", "Docker", "Terraform", "CI/CD"]} />
      
      <header className="cloud-header">
        <h2>Infrastructure Orchestration</h2>
        <button className="soc-scan-btn" onClick={fetchInfrastructureStatus} disabled={loading}>
          {loading ? 'Syncing Fleet...' : 'Sync All Modules'}
        </button>
      </header>

      <div className="infra-grid">
        {projects.length > 0 ? (
          projects.map((p, idx) => (
            <div key={idx} className="infra-card">
              <h4>{p.project || `Module P${idx + 1}`}</h4>
              <p className="text-green">● {p.status || 'Active'}</p>
            </div>
          ))
        ) : (
          <p>Click "Sync All Modules" to initialize infrastructure monitoring.</p>
        )}
      </div>
    </div>
  );
};

export default CloudPage;
